import { sql } from 'drizzle-orm';
import { check, index, integer, sqliteTable, text, uniqueIndex } from 'drizzle-orm/sqlite-core';

// Amounts are integer kobo. One reader point equals one kobo of airtime credit.
// All timestamps are Unix seconds. IDs are generated by trusted server code.
const now = sql`(unixepoch())`;

export const users = sqliteTable('users', {
  id: text('id').primaryKey().notNull(),
  email: text('email').notNull(),
  passwordHash: text('password_hash').notNull(),
  role: text('role', { enum: ['viewer', 'advertiser', 'admin'] }).notNull(),
  status: text('status', { enum: ['active', 'suspended'] }).notNull().default('active'),
  walletBalanceKobo: integer('wallet_balance_kobo').notNull().default(0),
  createdAt: integer('created_at').notNull().default(now),
}, t => [
  uniqueIndex('users_email_unique').on(t.email),
  check('users_role_check', sql`${t.role} in ('viewer','advertiser','admin')`),
  check('users_status_check', sql`${t.status} in ('active','suspended')`),
  check('users_balance_check', sql`typeof(${t.walletBalanceKobo}) = 'integer' and ${t.walletBalanceKobo} between 0 and 9007199254740991`),
]);

export const authSessions = sqliteTable('auth_sessions', {
  id: text('id').primaryKey().notNull(),
  userId: text('user_id').notNull().references(() => users.id, { onDelete: 'restrict' }),
  tokenHash: text('token_hash').notNull(),
  createdAt: integer('created_at').notNull().default(now),
  expiresAt: integer('expires_at').notNull(),
  revokedAt: integer('revoked_at'),
}, t => [uniqueIndex('auth_sessions_token_unique').on(t.tokenHash), index('auth_sessions_user_idx').on(t.userId), check('auth_session_expiry_check', sql`${t.expiresAt} > ${t.createdAt}`)]);

export const campaigns = sqliteTable('campaigns', {
  id: text('id').primaryKey().notNull(),
  advertiserId: text('advertiser_id').notNull().references(() => users.id, { onDelete: 'restrict' }),
  title: text('title').notNull(),
  kind: text('kind', { enum: ['article', 'app_install'] }).notNull(),
  status: text('status', { enum: ['draft', 'pending_review', 'active', 'paused', 'cancelled'] }).notNull().default('draft'),
  targetCountry: text('target_country').notNull().default('NG'),
  durationSeconds: integer('duration_seconds').notNull().default(60),
  cooldownSeconds: integer('cooldown_seconds').notNull().default(86400),
  pricePerActionKobo: integer('price_per_action_kobo').notNull(),
  viewerRewardKobo: integer('viewer_reward_kobo').notNull(),
  platformFeeKobo: integer('platform_fee_kobo').notNull(),
  remainingBudgetKobo: integer('remaining_budget_kobo').notNull().default(0),
  createdAt: integer('created_at').notNull().default(now),
}, t => [
  index('campaigns_owner_idx').on(t.advertiserId), index('campaigns_feed_idx').on(t.status, t.kind, t.targetCountry),
  check('campaign_kind_check', sql`${t.kind} in ('article','app_install')`),
  check('campaign_status_check', sql`${t.status} in ('draft','pending_review','active','paused','cancelled')`),
  check('campaign_country_check', sql`${t.targetCountry} glob '[A-Z][A-Z]'`),
  check('campaign_duration_check', sql`typeof(${t.durationSeconds}) = 'integer' and ${t.durationSeconds} >= 60`),
  check('campaign_cooldown_check', sql`typeof(${t.cooldownSeconds}) = 'integer' and ${t.cooldownSeconds} >= 0`),
  check('campaign_price_check', sql`typeof(${t.pricePerActionKobo}) = 'integer' and typeof(${t.viewerRewardKobo}) = 'integer' and typeof(${t.platformFeeKobo}) = 'integer' and ${t.pricePerActionKobo} between 1 and 9007199254740991 and ${t.viewerRewardKobo} > 0 and ${t.platformFeeKobo} >= 0 and ${t.viewerRewardKobo} + ${t.platformFeeKobo} = ${t.pricePerActionKobo} and (${t.kind} != 'app_install' or ${t.pricePerActionKobo} >= 1000)`),
  check('campaign_budget_check', sql`typeof(${t.remainingBudgetKobo}) = 'integer' and ${t.remainingBudgetKobo} between 0 and 9007199254740991`),
]);

export const feedSources = sqliteTable('feed_sources', {
  id: text('id').primaryKey().notNull(),
  campaignId: text('campaign_id').notNull().references(() => campaigns.id, { onDelete: 'restrict' }),
  feedUrl: text('feed_url').notNull(),
  status: text('status', { enum: ['pending_review', 'active', 'paused'] }).notNull().default('pending_review'),
  lastFetchedAt: integer('last_fetched_at'),
  createdAt: integer('created_at').notNull().default(now),
}, t => [index('feeds_campaign_idx').on(t.campaignId), check('feed_status_check', sql`${t.status} in ('pending_review','active','paused')`)]);

export const posts = sqliteTable('posts', {
  id: text('id').primaryKey().notNull(),
  campaignId: text('campaign_id').notNull().references(() => campaigns.id, { onDelete: 'restrict' }),
  feedId: text('feed_id').references(() => feedSources.id, { onDelete: 'restrict' }),
  canonicalUrl: text('canonical_url').notNull(),
  title: text('title').notNull(),
  description: text('description'),
  imageUrl: text('image_url'),
  category: text('category').notNull(),
  status: text('status', { enum: ['pending_review', 'active', 'removed'] }).notNull().default('pending_review'),
  createdAt: integer('created_at').notNull().default(now),
}, t => [uniqueIndex('posts_campaign_url_unique').on(t.campaignId,t.canonicalUrl), index('posts_public_idx').on(t.status,t.category), check('posts_status_check', sql`${t.status} in ('pending_review','active','removed')`)]);

export const taskSessions = sqliteTable('task_sessions', {
  id: text('id').primaryKey().notNull(),
  viewerId: text('viewer_id').notNull().references(() => users.id, { onDelete: 'restrict' }),
  postId: text('post_id').notNull().references(() => posts.id, { onDelete: 'restrict' }),
  tokenHash: text('token_hash').notNull(),
  startedAt: integer('started_at').notNull().default(now),
  expiresAt: integer('expires_at').notNull(),
  usedAt: integer('used_at'),
  startCountry: text('start_country').notNull(),
  startIp: text('start_ip').notNull(),
}, t => [uniqueIndex('task_token_unique').on(t.tokenHash), index('task_viewer_post_idx').on(t.viewerId,t.postId), check('task_expiry_check', sql`${t.expiresAt} > ${t.startedAt}`)]);

export const taskClaims = sqliteTable('task_claims', {
  id: text('id').primaryKey().notNull(),
  taskSessionId: text('task_session_id').notNull().references(() => taskSessions.id, { onDelete: 'restrict' }),
  viewerId: text('viewer_id').notNull().references(() => users.id, { onDelete: 'restrict' }),
  postId: text('post_id').notNull().references(() => posts.id, { onDelete: 'restrict' }),
  priceKobo: integer('price_kobo').notNull(),
  viewerRewardKobo: integer('viewer_reward_kobo').notNull(),
  platformFeeKobo: integer('platform_fee_kobo').notNull(),
  claimedAt: integer('claimed_at').notNull().default(now),
}, t => [uniqueIndex('claim_session_unique').on(t.taskSessionId), index('claim_cooldown_idx').on(t.viewerId,t.postId,t.claimedAt), check('claim_amount_check', sql`typeof(${t.priceKobo}) = 'integer' and typeof(${t.viewerRewardKobo}) = 'integer' and typeof(${t.platformFeeKobo}) = 'integer' and ${t.priceKobo} between 1 and 9007199254740991 and ${t.viewerRewardKobo} > 0 and ${t.platformFeeKobo} >= 0 and ${t.viewerRewardKobo} + ${t.platformFeeKobo} = ${t.priceKobo}`)]);

export const appSubmissions = sqliteTable('app_submissions', {
  id: text('id').primaryKey().notNull(),
  campaignId: text('campaign_id').notNull().references(() => campaigns.id, { onDelete: 'restrict' }),
  viewerId: text('viewer_id').notNull().references(() => users.id, { onDelete: 'restrict' }),
  screenshotKey: text('screenshot_key').notNull(),
  status: text('status', { enum: ['pending', 'approved', 'rejected'] }).notNull().default('pending'),
  submittedAt: integer('submitted_at').notNull().default(now),
  reviewedAt: integer('reviewed_at'),
  reviewedBy: text('reviewed_by').references(() => users.id, { onDelete: 'restrict' }),
}, t => [uniqueIndex('app_submission_campaign_viewer_unique').on(t.campaignId,t.viewerId), index('app_submission_queue_idx').on(t.campaignId,t.status,t.submittedAt), check('app_submission_status_check', sql`${t.status} in ('pending','approved','rejected')`)]);

export const deposits = sqliteTable('deposits', {
  id: text('id').primaryKey().notNull(),
  advertiserId: text('advertiser_id').notNull().references(() => users.id, { onDelete: 'restrict' }),
  reference: text('reference').notNull(),
  transactionId: text('transaction_id'),
  amountKobo: integer('amount_kobo').notNull(),
  currency: text('currency').notNull().default('NGN'),
  status: text('status', { enum: ['pending', 'succeeded', 'failed'] }).notNull().default('pending'),
  createdAt: integer('created_at').notNull().default(now),
  creditedAt: integer('credited_at'),
}, t => [uniqueIndex('deposit_reference_unique').on(t.reference), uniqueIndex('deposit_transaction_unique').on(t.transactionId), check('deposit_amount_check', sql`typeof(${t.amountKobo}) = 'integer' and ${t.amountKobo} between 1 and 9007199254740991`), check('deposit_currency_check', sql`${t.currency} = 'NGN'`), check('deposit_status_check', sql`${t.status} in ('pending','succeeded','failed')`)]);

export const airtimeRedemptions = sqliteTable('airtime_redemptions', {
  id: text('id').primaryKey().notNull(),
  viewerId: text('viewer_id').notNull().references(() => users.id, { onDelete: 'restrict' }),
  amountKobo: integer('amount_kobo').notNull(),
  phoneNumber: text('phone_number').notNull(),
  network: text('network').notNull(),
  status: text('status', { enum: ['pending', 'approved', 'rejected', 'fulfilled'] }).notNull().default('pending'),
  reviewedBy: text('reviewed_by').references(() => users.id, { onDelete: 'restrict' }),
  createdAt: integer('created_at').notNull().default(now),
  completedAt: integer('completed_at'),
}, t => [index('redemption_queue_idx').on(t.status,t.createdAt), check('redemption_amount_check', sql`typeof(${t.amountKobo}) = 'integer' and ${t.amountKobo} between 1 and 9007199254740991`), check('redemption_status_check', sql`${t.status} in ('pending','approved','rejected','fulfilled')`)]);

export const walletLedger = sqliteTable('wallet_ledger', {
  id: text('id').primaryKey().notNull(),
  userId: text('user_id').notNull().references(() => users.id, { onDelete: 'restrict' }),
  kind: text('kind', { enum: ['deposit_credit','campaign_funding','campaign_reallocation','task_reward','install_reward','redemption_reserve','redemption_refund'] }).notNull(),
  amountKobo: integer('amount_kobo').notNull(),
  idempotencyKey: text('idempotency_key').notNull(),
  createdAt: integer('created_at').notNull().default(now),
}, t => [uniqueIndex('ledger_idempotency_unique').on(t.idempotencyKey), index('ledger_user_idx').on(t.userId,t.createdAt), check('ledger_kind_check', sql`${t.kind} in ('deposit_credit','campaign_funding','campaign_reallocation','task_reward','install_reward','redemption_reserve','redemption_refund')`), check('ledger_amount_check', sql`typeof(${t.amountKobo}) = 'integer' and ${t.amountKobo} between -9007199254740991 and 9007199254740991 and ${t.amountKobo} != 0`)]);
